import { MeshStandardNodeMaterial } from 'three/webgpu';
import { color, uv, mix, smoothstep, vec3, uniform, positionLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  const activeTimelines = [];

  // ==========================================
  // 1. BACKDROP & HIGH-CONTRAST LIGHTING STAGE
  // ==========================================
  // Stylized textured backdrop with vertical gradient to prevent FLAT_VOID
  const bgGeo = new THREE.PlaneGeometry(10, 8);
  const bgMat = new MeshStandardNodeMaterial({
    roughness: 0.9,
    metalness: 0.2
  });
  const bgUV = uv();
  bgMat.colorNode = mix(color('#0b0b10'), color('#16161d'), bgUV.y);

  const bgMesh = new THREE.Mesh(bgGeo, bgMat);
  bgMesh.position.set(0, 0, -2.0);
  group.add(bgMesh);

  // Rim lights & Key lights to highlight the physical chamfered button
  const keyLight = new THREE.DirectionalLight('#ffffff', 1.4);
  keyLight.position.set(2, 4, 3);
  group.add(keyLight);

  const fillLight = new THREE.DirectionalLight('#e8ecf2', 0.6);
  fillLight.position.set(-3, -2, 1);
  group.add(fillLight);

  const accentRim = new THREE.DirectionalLight('#ff2a38', 1.5);
  accentRim.position.set(-2, 3, 2);
  group.add(accentRim);

  // ==========================================
  // 2. CONTACT SHADOW
  // ==========================================
  const shadowGeo = new THREE.PlaneGeometry(3.0, 1.0);
  const shadowMat = new THREE.MeshBasicMaterial({
    color: 0x010103,
    transparent: true,
    opacity: 0.35,
    depthWrite: false
  });
  const shadowMesh = new THREE.Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -0.65, -0.05);
  shadowMesh.rotation.x = -Math.PI * 0.1; // subtly angled shadow plane
  group.add(shadowMesh);

  // ==========================================
  // 3. CTA BUTTON (Extruded Rounded Rect with physical chamfer)
  // ==========================================
  const buttonWidth = 2.6;
  const buttonHeight = 0.68;
  const cornerRadius = 0.08;

  const shape = new THREE.Shape();
  const x = -buttonWidth / 2;
  const y = -buttonHeight / 2;

  shape.moveTo(x + cornerRadius, y);
  shape.lineTo(x + buttonWidth - cornerRadius, y);
  shape.quadraticCurveTo(x + buttonWidth, y, x + buttonWidth, y + cornerRadius);
  shape.lineTo(x + buttonWidth, y + buttonHeight - cornerRadius);
  shape.quadraticCurveTo(x + buttonWidth, y + buttonHeight, x + buttonWidth - cornerRadius, y + buttonHeight);
  shape.lineTo(x + cornerRadius, y + buttonHeight);
  shape.quadraticCurveTo(x, y + buttonHeight, x, y + buttonHeight - cornerRadius);
  shape.lineTo(x, y + cornerRadius);
  shape.quadraticCurveTo(x, y, x + cornerRadius, y);

  const extrudeSettings = {
    depth: 0.03,
    bevelEnabled: true,
    bevelSegments: 4,
    steps: 1,
    bevelSize: 0.015,
    bevelThickness: 0.015
  };

  const buttonGeo = new THREE.ExtrudeGeometry(shape, extrudeSettings);
  buttonGeo.center();

  // Uniform for interactive edge glow state
  const hoverVal = uniform(0.0);

  const btnMaterial = new MeshStandardNodeMaterial({
    roughness: 0.5,
    metalness: 0.35,
    clearcoat: 0.22
  });

  // Engineered gradient TSL implementation using local positions to ensure perfect alignments
  const localPos = positionLocal;
  const gradY = localPos.y.add(buttonHeight / 2).div(buttonHeight); // 0.0 to 1.0

  const c0 = color('#ff4450');
  const c1 = color('#ff2a38');
  const c2 = color('#c1121f');

  // Hard 0.01-unit seam line at 50% face height
  const seamWidth = 0.005;
  const isSeam = smoothstep(0.0, seamWidth, localPos.y.abs());
  const upperGrad = mix(c1, c0, gradY.sub(0.5).mul(2.0));
  const lowerGrad = mix(c2, c1, gradY.mul(2.0));
  const gradMixFactor = smoothstep(-0.001, 0.001, localPos.y);
  const baseGradient = mix(lowerGrad, upperGrad, gradMixFactor).mul(isSeam);

  // Perimeter emissive channel 0.015 units wide in #ff2a38 at dynamic intensity
  const borderEdgeX = smoothstep(buttonWidth / 2 - 0.02, buttonWidth / 2 - 0.005, localPos.x.abs());
  const borderEdgeY = smoothstep(buttonHeight / 2 - 0.02, buttonHeight / 2 - 0.005, localPos.y.abs());
  const edgeMask = borderEdgeX.max(borderEdgeY);

  const glowIntensity = mix(1.6, 2.2, hoverVal);
  const perimeterEmissive = color('#ff2a38').mul(edgeMask).mul(glowIntensity);

  btnMaterial.colorNode = baseGradient;
  btnMaterial.emissiveNode = perimeterEmissive;

  const buttonMesh = new THREE.Mesh(buttonGeo, btnMaterial);
  buttonMesh.position.set(0, 0, 0);
  group.add(buttonMesh);

  // ==========================================
  // 4. TYPOGRAPHY / TEXT
  // ==========================================
  // "BEGIN COMMISSION" Centered over button
  const ctaLabel = ctx.fontAtlas.createText('BEGIN COMMISSION', {
    fontSize: 0.16,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 6
  });
  ctaLabel.position.set(0, -0.05, 0.06); // raised forward
  buttonMesh.add(ctaLabel);

  // "NO DEPOSIT REQUIRED" 0.25 below button
  const captionLabel = ctx.fontAtlas.createText('NO DEPOSIT REQUIRED', {
    fontSize: 0.08,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 10
  });
  captionLabel.position.set(0, -0.62, 0.02);
  group.add(captionLabel);

  // ==========================================
  // 5. ANIMATIONS & INTERACTIONS
  // ==========================================
  // Entrance Settle: 1.04 -> 1.0 scale over 900ms
  buttonMesh.scale.set(1.04, 1.04, 1.04);
  const entranceTl = gsap.to(buttonMesh.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'power4.out'
  });
  activeTimelines.push(entranceTl);

  const onPointerOver = () => {
    // Hover: translateZ to 0.06 and edge emissive intensity 1.6 -> 2.2
    gsap.to(buttonMesh.position, {
      z: 0.06,
      duration: 0.18,
      ease: 'power2.out'
    });
    gsap.to(hoverVal, {
      value: 1.0,
      duration: 0.18,
      ease: 'power2.out'
    });
  };

  const onPointerOut = () => {
    gsap.to(buttonMesh.position, {
      z: 0,
      duration: 0.25,
      ease: 'power2.out'
    });
    gsap.to(hoverVal, {
      value: 0.0,
      duration: 0.25,
      ease: 'power2.out'
    });
    gsap.to(buttonMesh.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.2
    });
  };

  const onPointerDown = () => {
    // Press scale 1.0 -> 0.97
    gsap.to(buttonMesh.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'power1.out'
    });
    // Deepen shadow
    gsap.to(shadowMat, {
      opacity: 0.55,
      duration: 0.12
    });
    gsap.to(shadowMesh.scale, {
      x: 0.85,
      y: 0.85,
      duration: 0.12
    });
  };

  const onPointerUp = () => {
    gsap.to(buttonMesh.scale, {
      x: 1.0,
      y: 1.0,
      z: 1.0,
      duration: 0.2,
      ease: 'power2.out'
    });
    gsap.to(shadowMat, {
      opacity: 0.35,
      duration: 0.2
    });
    gsap.to(shadowMesh.scale, {
      x: 1.0,
      y: 1.0,
      duration: 0.2
    });

    ctx.emit('navigate', { to: 'hub-features' });
  };

  group.userData.handlers = {
    pointerover: onPointerOver,
    pointerout: onPointerOut,
    pointerdown: onPointerDown,
    pointerup: onPointerUp
  };

  group.userData.cleanup = () => {
    activeTimelines.forEach((tl) => tl.kill());
    bgMat.dispose();
    bgGeo.dispose();
    buttonGeo.dispose();
    btnMaterial.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
  };

  return group;
}
